questionvariables.text:
baseidx : rand_with_prohib(1,3,[]);
signidx : rand(2);
basedeg : [30,45,60][baseidx];
thetadeg : if signidx=1 then -basedeg else basedeg;
ta : if signidx=1 then -( if baseidx=1 then 1/2 elseif baseidx=2 then sqrt(2)/2 else sqrt(3)/2)
     else (if baseidx=1 then 1/2 elseif baseidx=2 then sqrt(2)/2 else sqrt(3)/2);
wrong_inverse_again : thetadeg;          /* applied sin^{-1} a second time, or just copied the angle as if it were x */
